mapper.delete:
BEGIN
    DELETE FROM notice WHERE project_id = #{projectId};
    DELETE FROM meeting_minutes WHERE project_id = #{projectId};
    DELETE FROM calendar_events WHERE project_id = #{projectId};
    DELETE FROM project_reports WHERE project_id = #{projectId};
    DELETE FROM team_reports WHERE project_id = #{projectId};
    DELETE FROM sub_tasks WHERE project_id = #{projectId};
    DELETE FROM tasks WHERE project_id = #{projectId};
    DELETE FROM project_members WHERE project_id = #{projectId};
    DELETE FROM projects WHERE project_id = #{projectId};
END;

mapper.select:
SELECT pm.role
FROM project_members pm
JOIN workspace_members wm ON pm.workspace_member_id = wm.workspace_member_id
WHERE pm.project_id = #{projectId}
  AND wm.member_id = #{memberId}
